import React, { useEffect, useState, useRef } from 'react';
import { ExternalLink, Github, ArrowUpRight, Play } from 'lucide-react';

export default function ProjectsSection() {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeProject, setActiveProject] = useState(0);
  const sectionRef = useRef(null);

  const projects = [
    {
      title: 'Techzo',
      subtitle: 'Design Agency Template',
      description:
        'Techzo is a cutting-edge design agency template built to showcase innovation, digital expertise, and a bold creative presence online',
      tags: ['HTML5 & CSS', 'Framer Motion', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/1827805025.jpeg',
      gradient: 'from-blue-600/20 via-purple-600/20 to-pink-600/20',
      textGradient: 'from-blue-400 to-purple-400',
      accentColor: 'blue',
      year: '2024',
      category: 'Web Design',
    },
    {
      title: 'Lumin Studio',
      subtitle: 'Modern Design Portfolio',
      description:
        'LuminStudio blends elegance and clarity — a modern design agency template crafted to highlight creative work and impress potential clients',
      tags: ['HTML5 & Tailwind CSS', 'React', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/429890704.jpeg',
      gradient: 'from-emerald-600/20 via-teal-600/20 to-cyan-600/20',
      textGradient: 'from-emerald-400 to-teal-400',
      accentColor: 'emerald',
      year: '2024',
      category: 'Portfolio',
    },
    {
      title: 'Nubuilt',
      subtitle: 'Architecture Template',
      description:
        'Crafted with clean, semantic code — Nubuilt is a sleek architecture template built for performance, responsiveness, and timeless design.',
      tags: ['HTML5', 'CSS', 'GSAP'],
      image: 'https://ext.same-assets.com/498039404/1730903789.jpeg',
      gradient: 'from-orange-600/20 via-red-600/20 to-pink-600/20',
      textGradient: 'from-orange-400 to-red-400',
      accentColor: 'orange',
      year: '2023',
      category: 'Architecture',
    },
    {
      title: 'Design Orbit',
      subtitle: 'Portfolio Website Template',
      description:
        'Bold, creative, and conversion-focused — DesignOrbit is a sleek portfolio website template made for design agencies to showcase their work and attract clients.',
      tags: ['HTML5 & CSS', 'GSAP', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/3079166500.jpeg',
      gradient: 'from-violet-600/20 via-purple-600/20 to-indigo-600/20',
      textGradient: 'from-violet-400 to-purple-400',
      accentColor: 'violet',
      year: '2023',
      category: 'Creative',
    },
  ];

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const sectionTop = sectionRef.current.offsetTop;
      const scrollY = window.scrollY;
      const windowHeight = window.innerHeight;

      // Calculate scroll progress within the section, including CTA
      const sectionHeight = windowHeight * (projects.length + 1);
      const scrollWithinSection = Math.max(0, scrollY - sectionTop);
      const progress = Math.min(scrollWithinSection / (sectionHeight - windowHeight), 1);

      setScrollProgress(progress);

      // Calculate active project
      const currentProject = Math.floor((scrollWithinSection / windowHeight) * projects.length);
      setActiveProject(Math.min(currentProject, projects.length - 1));
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial call

    return () => window.removeEventListener('scroll', handleScroll);
  }, [projects.length]);

  return (
    <section ref={sectionRef} className="relative">
      {/* Projects Container */}
      <div style={{ height: `${(projects.length + 1) * 100}vh` }}>
        {projects.map((project, index) => {
          // Calculate translateY based on scroll progress
          const projectStart = index / (projects.length + 1);
          const projectEnd = (index + 1) / (projects.length + 1);
          const progressWithinProject = Math.max(
            0,
            Math.min((scrollProgress - projectStart) / (projectEnd - projectStart), 1),
          );
          const translateY = progressWithinProject * 100;

          return (
            <div
              key={index}
              className="absolute top-0 w-full h-screen flex items-center justify-center overflow-hidden transition-transform duration-700 ease-out"
              style={{
                transform: `translateY(-${translateY}%)`,
                zIndex: projects.length - index,
              }}
            >
              {/* Enhanced Background */}
              <div
                className="absolute inset-0"
                style={{
                  background: `
                    radial-gradient(circle at 20% 30%, rgba(59, 130, 246, 0.15) 0%, transparent 60%),
                    radial-gradient(circle at 80% 70%, rgba(168, 85, 247, 0.15) 0%, transparent 60%),
                    radial-gradient(circle at 40% 80%, rgba(34, 197, 94, 0.1) 0%, transparent 50%),
                    linear-gradient(135deg, rgba(0, 0, 0, 0.97) 0%, rgba(15, 23, 42, 0.99) 100%)
                  `,
                }}
              />

              {/* Animated Mesh Background */}
              <div className="absolute inset-0 opacity-30">
                <div
                  className="absolute inset-0"
                  style={{
                    backgroundImage: `
                      radial-gradient(circle at 25% 25%, rgba(59, 130, 246, 0.1) 0%, transparent 50%),
                      radial-gradient(circle at 75% 75%, rgba(168, 85, 247, 0.1) 0%, transparent 50%)
                    `,
                    backgroundSize: '100px 100px',
                    animation: 'float 20s ease-in-out infinite',
                  }}
                />
              </div>

              {/* Content Container */}
              <div className="relative z-10 w-full max-w-7xl mx-auto px-6 lg:px-16">
                <div className="grid lg:grid-cols-12 gap-8 items-center min-h-screen py-20">
                  {/* Left Content - Enhanced */}
                  <div className="lg:col-span-5 space-y-8">
                    {/* Project Meta */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-8 h-px bg-gradient-to-r from-white/60 to-transparent" />
                        <span className="text-xs text-gray-400 font-mono tracking-widest uppercase">
                          {project.category}
                        </span>
                      </div>
                      <div className="text-xs text-gray-500 font-mono">{project.year}</div>
                    </div>

                    {/* Project Title - Enhanced */}
                    <div className="space-y-6">
                      <div className="space-y-2">
                        <h2
                          className={`text-4xl lg:text-6xl xl:text-7xl font-black bg-gradient-to-r ${project.textGradient} bg-clip-text text-transparent leading-[0.9] tracking-tight`}
                        >
                          {project.title}
                        </h2>
                        <p className="text-lg text-gray-400 font-light tracking-wide">{project.subtitle}</p>
                      </div>

                      {/* Project Number */}
                      <div className="flex items-center gap-4">
                        <div className="text-6xl font-black text-white/10">{String(index + 1).padStart(2, '0')}</div>
                        <div className="w-12 h-px bg-gradient-to-r from-white/20 to-transparent" />
                      </div>
                    </div>

                    {/* Description - Enhanced */}
                    <div className="space-y-6">
                      <p className="text-base text-gray-300 leading-relaxed max-w-md font-light">
                        {project.description}
                      </p>

                      {/* Tech Stack - Modern Pills */}
                      <div className="flex flex-wrap gap-2">
                        {project.tags.map((tag, tagIndex) => (
                          <div
                            key={tag}
                            className="group relative overflow-hidden px-4 py-2 bg-white/5 backdrop-blur-xl border border-white/10 rounded-full text-xs font-medium text-white/80 hover:text-white hover:bg-white/10 transition-all duration-300 hover:scale-105 cursor-pointer"
                            style={{
                              animationDelay: `${tagIndex * 0.1}s`,
                            }}
                          >
                            <div className="absolute inset-0 bg-gradient-to-r from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                            <span className="relative z-10">{tag}</span>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Action Buttons - Redesigned */}
                    <div className="flex gap-4 pt-4">
                      <button className="group relative px-6 py-3 bg-white text-black font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:shadow-2xl hover:shadow-white/20">
                        <div className="absolute inset-0 bg-gradient-to-r from-gray-100 to-white opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                        <span className="relative z-10 flex items-center gap-2">
                          <Play className="w-4 h-4" />
                          Live Demo
                          <ArrowUpRight className="w-4 h-4 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform duration-300" />
                        </span>
                      </button>

                      <button className="group relative px-6 py-3 bg-transparent border border-white/20 text-white font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:bg-white/10">
                        <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                        <span className="relative z-10 flex items-center gap-2">
                          <Github className="w-4 h-4 group-hover:rotate-12 transition-transform duration-300" />
                          Source Code
                        </span>
                      </button>
                    </div>
                  </div>

                  {/* Right Content - Enhanced Project Showcase */}
                  <div className="lg:col-span-7 relative">
                    {/* Main Project Card */}
                    <div className="relative group">
                      {/* Card Container with Glass Effect */}
                      <div className="relative rounded-3xl overflow-hidden bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-2xl border border-white/20 hover:border-white/30 transition-all duration-700 hover:scale-[1.02] hover:shadow-2xl hover:shadow-black/50">
                        {/* Image Container */}
                        <div className="relative aspect-[4/3] overflow-hidden">
                          <img
                            src={project.image || '/assets/placeholder.svg'}
                            alt={project.title}
                            className="w-full h-full object-cover transition-all duration-700 group-hover:scale-110"
                          />

                          {/* Image Overlay */}
                          <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-60 group-hover:opacity-40 transition-opacity duration-500" />

                          {/* Floating Action Button */}
                          <div className="absolute top-6 right-6 w-12 h-12 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                            <ExternalLink className="w-5 h-5 text-white" />
                          </div>

                          {/* Status Indicator */}
                          <div className="absolute top-6 left-6 flex items-center gap-2 px-3 py-1.5 bg-black/40 backdrop-blur-xl border border-white/20 rounded-full">
                            <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
                            <span className="text-xs text-white font-medium">Live</span>
                          </div>
                        </div>

                        {/* Card Footer */}
                        <div className="p-6 space-y-4">
                          <div className="flex items-center justify-between">
                            <div>
                              <h3 className="text-xl font-bold text-white mb-1">{project.title}</h3>
                              <p className="text-sm text-gray-400">
                                {project.category} • {project.year}
                              </p>
                            </div>
                            <div className="flex gap-2">
                              <div className="w-8 h-8 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center hover:bg-white/20 transition-colors duration-300 cursor-pointer">
                                <Github className="w-4 h-4 text-white" />
                              </div>
                              <div className="w-8 h-8 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center hover:bg-white/20 transition-colors duration-300 cursor-pointer">
                                <ExternalLink className="w-4 h-4 text-white" />
                              </div>
                            </div>
                          </div>

                          {/* Progress Bar */}
                          <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                            <div
                              className="h-full bg-gradient-to-r from-white/60 to-white/40 rounded-full transition-all duration-1000"
                              style={{
                                width: index === activeProject ? '100%' : '0%',
                              }}
                            />
                          </div>
                        </div>

                        {/* Glow Effect */}
                        <div className="absolute -inset-1 bg-gradient-to-r from-white/10 via-transparent to-white/10 rounded-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 blur-xl -z-10" />
                      </div>

                      {/* Decorative Elements */}
                      <div className="absolute -top-4 -right-4 w-24 h-24 bg-gradient-to-r from-blue-500/20 to-purple-500/20 rounded-full blur-2xl animate-pulse" />
                      <div className="absolute -bottom-4 -left-4 w-32 h-32 bg-gradient-to-r from-emerald-500/20 to-teal-500/20 rounded-full blur-2xl animate-pulse" />
                    </div>
                  </div>
                </div>
              </div>

              {/* Enhanced Progress Indicator */}
              <div className="absolute bottom-8 right-8 flex items-center gap-6 text-white/60">
                <div className="flex flex-col items-end gap-2">
                  <span className="text-xs font-mono tracking-wider">PROJECT</span>
                  <span className="text-lg font-bold">
                    {String(index + 1).padStart(2, '0')} / {String(projects.length).padStart(2, '0')}
                  </span>
                </div>
                <div className="flex flex-col gap-2">
                  {projects.map((_, dotIndex) => (
                    <div
                      key={dotIndex}
                      className={`w-1 h-8 rounded-full transition-all duration-500 ${
                        dotIndex === activeProject
                          ? 'bg-white scale-110'
                          : dotIndex < activeProject
                          ? 'bg-white/60'
                          : 'bg-white/20'
                      }`}
                    />
                  ))}
                </div>
              </div>

              {/* Scroll Indicator (only on first project) */}
              {index === 0 && (
                <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 text-white/40">
                  <div className="flex flex-col items-center gap-3 animate-bounce">
                    <span className="text-xs font-mono tracking-widest">SCROLL TO EXPLORE</span>
                    <div className="w-px h-12 bg-gradient-to-b from-white/60 to-transparent" />
                  </div>
                </div>
              )}
            </div>
          );
        })}

        {/* Enhanced Final CTA Section */}
        <div
  className="sticky top-0 w-full h-screen flex items-center justify-center overflow-hidden transition-transform duration-700 ease-out"
  style={{
    transform: `translateY(-${Math.max(0, (scrollProgress - projects.length / (projects.length + 1)) * (projects.length + 1) * 100)}%)`,
    zIndex: 0,
  }}
>
          {/* Background */}
          <div
            className="absolute inset-0"
            style={{
              background: `
                radial-gradient(circle at 30% 20%, rgba(59, 130, 246, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 70% 80%, rgba(168, 85, 247, 0.1) 0%, transparent 50%),
                linear-gradient(135deg, rgba(0, 0, 0, 0.98) 0%, rgba(15, 23, 42, 1) 100%)
              `,
            }}
          />

          <div className="relative z-10 text-center space-y-12 px-6 max-w-4xl mx-auto">
            <div className="space-y-6">
              <div className="flex items-center justify-center gap-4 mb-8">
                <div className="w-12 h-px bg-gradient-to-r from-transparent via-white/40 to-transparent" />
                <span className="text-sm text-gray-400 font-mono tracking-wider">READY TO COLLABORATE?</span>
                <div className="w-12 h-px bg-gradient-to-r from-transparent via-white/40 to-transparent" />
              </div>
              <h3 className="text-5xl lg:text-7xl font-black text-white leading-tight">
                Let's Build Something
                <br />
                <span className="bg-gradient-to-r from-teal-400 to-blue-400 bg-clip-text text-transparent">
                  Amazing Together
                </span>
              </h3>
              <p className="text-xl text-gray-400 max-w-2xl mx-auto leading-relaxed">
                Ready to transform your vision into reality? Let's collaborate and create exceptional digital experiences
                that make an impact.
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <button
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = '/assets/BadrEddineDiyaf.pdf';
                  link.download = 'Badr_Eddine_Diyaf_CV.pdf';
                  link.click();
                }}
                className="group relative px-8 py-4 text-lg bg-gradient-to-r from-teal-500 to-blue-500 text-white font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:shadow-2xl hover:shadow-teal-500/25"
              >
                <div className="absolute inset-0 bg-gradient-to-r from-teal-600 to-blue-600 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                <span className="relative z-10 flex items-center justify-center gap-2">
